@startuml

class SensorController {
  + inhabitants : Inhabitant[]
  + apartment : Apartment
}

class Inhabitant {
  + username : string
  + password : string
  + email : string
  + isAdmin : boolean
}

class Apartment {
  + address : string
}

class Room {
  + description : string
}

abstract class Sensor {
  + vendorId : string
  + description : string
  + unit : Unit
  + threshold : float
}

class TemperatureSensor extends Sensor {
  + minValue : float
  + maxValue : float
}

class PowerSensor extends Sensor {
  + totalPowerConsumption : float
}

enum Unit {
  CELSIUS
  WATT
}

class MeasuredValue {
  + timestamp : datetime
  + value : float
}

class EMonitor {}

Apartment "1" *-- "2..*" Room
Room "1" *-- "*" Sensor
SensorController "1" o-- "*" Sensor
SensorController "1" --> "1" Apartment
Inhabitant "*" -- "1" SensorController
Inhabitant "1" --> "*" Sensor : queries
Sensor "1" *-- "1" MeasuredValue : lastValue
Sensor "1" *-- "*" MeasuredValue
EMonitor "1" --> "*" Sensor : checksThresholds
EMonitor "1" --> "1" SensorController : sendsAlerts via

@enduml

